import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import Home from "@/pages/Home";
import Identify from "@/pages/Identify";
import Result from "@/pages/Result";
import Family from "@/pages/Family";
import Learn from "@/pages/Learn";
import ScenarioDetail from "@/pages/ScenarioDetail";
import Profile from "@/pages/Profile";
import BottomNav from "@/components/layout/BottomNav";
import { useAppStore } from "@/store/useAppStore";
import { useEffect } from "react";

function AppContent() {
  const { user } = useAppStore();

  useEffect(() => {
    if (user.settings.fontSize === 'large') {
      document.documentElement.classList.add('font-large');
      document.documentElement.classList.remove('font-xlarge');
    } else if (user.settings.fontSize === 'xlarge') {
      document.documentElement.classList.add('font-xlarge');
      document.documentElement.classList.remove('font-large');
    } else {
      document.documentElement.classList.remove('font-large', 'font-xlarge');
    }
  }, [user.settings.fontSize]);

  return (
    <div className="min-h-screen bg-warm-50">
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/identify" element={<Identify />} />
        <Route path="/result/:id" element={<Result />} />
        <Route path="/family" element={<Family />} />
        <Route path="/learn" element={<Learn />} />
        <Route path="/learn/scenario/:id" element={<ScenarioDetail />} />
        <Route path="/profile" element={<Profile />} />
      </Routes>
      <BottomNav />
    </div>
  );
}

export default function App() {
  return (
    <Router>
      <AppContent />
    </Router>
  );
}
