import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  User, 
  Settings, 
  Clock, 
  Shield,
  ChevronRight,
  Volume2,
  Type,
  Moon,
  Bell,
  HelpCircle,
  Info,
  LogOut
} from 'lucide-react';
import PageContainer from '@/components/layout/PageContainer';
import Card from '@/components/ui/Card';
import RiskLevelBadge from '@/components/ui/RiskLevelBadge';
import { useAppStore } from '@/store/useAppStore';
import { formatDate, getIdentifyTypeText } from '@/utils/helpers';
import type { FontSize } from '@/types';

export default function Profile() {
  const navigate = useNavigate();
  const { user, history, setFontSize, updateSettings } = useAppStore();
  const [showFontPicker, setShowFontPicker] = useState(false);

  const fontSizeOptions: { value: FontSize; label: string; size: string }[] = [
    { value: 'normal', label: '标准', size: 'text-base' },
    { value: 'large', label: '较大', size: 'text-lg' },
    { value: 'xlarge', label: '特大', size: 'text-xl' },
  ];

  const handleFontSizeChange = (size: FontSize) => {
    setFontSize(size);
    if (size === 'normal') {
      document.documentElement.classList.remove('font-large', 'font-xlarge');
    } else if (size === 'large') {
      document.documentElement.classList.add('font-large');
      document.documentElement.classList.remove('font-xlarge');
    } else {
      document.documentElement.classList.add('font-xlarge');
      document.documentElement.classList.remove('font-large');
    }
  };

  const totalIdentified = history.length;
  const highRiskCount = history.filter(h => h.riskLevel === 'high').length;

  const settingsItems = [
    {
      icon: Type,
      label: '字体大小',
      value: fontSizeOptions.find(o => o.value === user.settings.fontSize)?.label || '标准',
      onClick: () => setShowFontPicker(true),
    },
    {
      icon: Volume2,
      label: '语音播报',
      value: user.settings.voiceBroadcast ? '开启' : '关闭',
      toggle: true,
      toggleValue: user.settings.voiceBroadcast,
      onToggle: () => updateSettings({ voiceBroadcast: !user.settings.voiceBroadcast }),
    },
    {
      icon: Bell,
      label: '亲情提醒',
      value: user.settings.familyNotification ? '开启' : '关闭',
      toggle: true,
      toggleValue: user.settings.familyNotification,
      onToggle: () => updateSettings({ familyNotification: !user.settings.familyNotification }),
    },
    {
      icon: Moon,
      label: '深色模式',
      value: user.settings.darkMode ? '开启' : '关闭',
      toggle: true,
      toggleValue: user.settings.darkMode,
      onToggle: () => updateSettings({ darkMode: !user.settings.darkMode }),
    },
  ];

  const otherItems = [
    { icon: HelpCircle, label: '使用帮助', onClick: () => {} },
    { icon: Info, label: '关于我们', onClick: () => {} },
    { icon: LogOut, label: '退出登录', onClick: () => {}, danger: true },
  ];

  return (
    <PageContainer title="我的" showBottomNav>
      {/* 用户信息 */}
      <div className="px-4 pt-6 pb-4 bg-gradient-to-b from-primary-50 to-warm-50">
        <div className="flex items-center gap-4">
          <div className="w-20 h-20 bg-primary-100 rounded-full flex items-center justify-center text-4xl">
            👵
          </div>
          <div className="flex-1">
            <h2 className="text-2xl font-bold text-text-primary">{user.name}</h2>
            <p className="text-text-secondary mt-1">{user.phone}</p>
          </div>
          <button className="p-2 hover:bg-white/50 rounded-full transition-colors">
            <Settings size={24} className="text-text-secondary" />
          </button>
        </div>

        {/* 统计数据 */}
        <div className="grid grid-cols-3 gap-3 mt-6">
          <Card className="p-3 text-center">
            <p className="text-2xl font-bold text-primary-500">{totalIdentified}</p>
            <p className="text-xs text-text-tertiary mt-1">识别次数</p>
          </Card>
          <Card className="p-3 text-center">
            <p className="text-2xl font-bold text-danger-500">{highRiskCount}</p>
            <p className="text-xs text-text-tertiary mt-1">高风险拦截</p>
          </Card>
          <Card className="p-3 text-center">
            <p className="text-2xl font-bold text-safe-500">
              {totalIdentified > 0 ? Math.round((totalIdentified - highRiskCount) / totalIdentified * 100) : 100}%
            </p>
            <p className="text-xs text-text-tertiary mt-1">安全率</p>
          </Card>
        </div>
      </div>

      {/* 识别历史 */}
      <div className="px-4 py-4">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-lg font-bold text-text-primary">识别历史</h2>
          <span className="text-sm text-text-tertiary">共 {history.length} 条</span>
        </div>

        {history.length > 0 ? (
          <div className="space-y-3">
            {history.slice(0, 5).map((record) => (
              <Card
                key={record.id}
                hover
                onClick={() => navigate(`/result/${record.id}`)}
                className="p-4"
              >
                <div className="flex items-start justify-between gap-4">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                      <span className="text-xs text-text-tertiary">
                        {getIdentifyTypeText(record.type)}
                      </span>
                      <span className="text-xs text-text-tertiary">·</span>
                      <span className="text-xs text-text-tertiary">
                        {formatDate(record.createdAt)}
                      </span>
                    </div>
                    <p className="text-text-primary line-clamp-1">
                      {record.content.length > 40
                        ? record.content.slice(0, 40) + '...'
                        : record.content}
                    </p>
                  </div>
                  <RiskLevelBadge level={record.riskLevel} size="sm" />
                </div>
              </Card>
            ))}
          </div>
        ) : (
          <Card className="p-8 text-center">
            <div className="w-16 h-16 mx-auto bg-gray-100 rounded-full flex items-center justify-center mb-4">
              <Clock size={32} className="text-gray-400" />
            </div>
            <p className="text-text-secondary">暂无识别记录</p>
            <button
              onClick={() => navigate('/identify')}
              className="mt-4 text-primary-500 font-medium"
            >
              去识别
            </button>
          </Card>
        )}
      </div>

      {/* 设置 */}
      <div className="px-4 py-4">
        <h2 className="text-lg font-bold text-text-primary mb-4">设置</h2>
        <Card className="overflow-hidden">
          {settingsItems.map((item, index) => {
            const Icon = item.icon;
            return (
              <div
                key={index}
                className="flex items-center justify-between p-4 border-b border-gray-50 last:border-0 cursor-pointer hover:bg-gray-50 transition-colors"
                onClick={item.onClick}
              >
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-primary-50 rounded-xl flex items-center justify-center">
                    <Icon size={20} className="text-primary-500" />
                  </div>
                  <span className="font-medium text-text-primary">{item.label}</span>
                </div>
                <div className="flex items-center gap-2">
                  {item.toggle ? (
                    <div
                      className={`w-12 h-7 rounded-full transition-colors relative ${
                        item.toggleValue ? 'bg-primary-500' : 'bg-gray-200'
                      }`}
                      onClick={(e) => {
                        e.stopPropagation();
                        item.onToggle?.();
                      }}
                    >
                      <div
                        className={`absolute top-1 w-5 h-5 bg-white rounded-full shadow transition-transform ${
                          item.toggleValue ? 'translate-x-6' : 'translate-x-1'
                        }`}
                      />
                    </div>
                  ) : (
                    <>
                      <span className="text-text-tertiary">{item.value}</span>
                      <ChevronRight size={20} className="text-text-tertiary" />
                    </>
                  )}
                </div>
              </div>
            );
          })}
        </Card>
      </div>

      {/* 其他 */}
      <div className="px-4 py-4 pb-8">
        <Card className="overflow-hidden">
          {otherItems.map((item, index) => {
            const Icon = item.icon;
            return (
              <div
                key={index}
                className="flex items-center justify-between p-4 border-b border-gray-50 last:border-0 cursor-pointer hover:bg-gray-50 transition-colors"
                onClick={item.onClick}
              >
                <div className="flex items-center gap-3">
                  <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${
                    item.danger ? 'bg-danger-50' : 'bg-gray-100'
                  }`}>
                    <Icon size={20} className={item.danger ? 'text-danger-500' : 'text-text-secondary'} />
                  </div>
                  <span className={`font-medium ${
                    item.danger ? 'text-danger-500' : 'text-text-primary'
                  }`}>
                    {item.label}
                  </span>
                </div>
                <ChevronRight size={20} className="text-text-tertiary" />
              </div>
            );
          })}
        </Card>

        <p className="text-center text-xs text-text-tertiary mt-6">
          银龄守护 v1.0.0
        </p>
      </div>

      {/* 字体大小选择弹窗 */}
      {showFontPicker && (
        <div 
          className="fixed inset-0 bg-black/50 z-50 flex items-end justify-center animate-fade-in"
          onClick={() => setShowFontPicker(false)}
        >
          <div 
            className="w-full max-w-lg bg-white rounded-t-3xl p-6 animate-slide-up"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="w-12 h-1 bg-gray-300 rounded-full mx-auto mb-6" />
            
            <h3 className="text-xl font-bold text-text-primary text-center mb-6">
              字体大小
            </h3>

            <div className="space-y-3">
              {fontSizeOptions.map((option) => {
                const isSelected = user.settings.fontSize === option.value;
                return (
                  <button
                    key={option.value}
                    onClick={() => handleFontSizeChange(option.value)}
                    className={`w-full p-4 rounded-2xl text-left transition-all border-2 ${
                      isSelected
                        ? 'border-primary-500 bg-primary-50'
                        : 'border-gray-200 bg-white hover:border-gray-300'
                    }`}
                  >
                    <div className="flex items-center justify-between">
                      <span className={`font-medium ${option.size} ${
                        isSelected ? 'text-primary-600' : 'text-text-primary'
                      }`}>
                        {option.label}字体
                      </span>
                      {isSelected && (
                        <div className="w-6 h-6 bg-primary-500 rounded-full flex items-center justify-center">
                          <span className="text-white text-sm">✓</span>
                        </div>
                      )}
                    </div>
                  </button>
                );
              })}
            </div>

            <button
              onClick={() => setShowFontPicker(false)}
              className="w-full mt-6 py-4 bg-primary-500 text-white rounded-2xl font-bold text-lg"
            >
              确定
            </button>
          </div>
        </div>
      )}
    </PageContainer>
  );
}
