import { cn } from '@/lib/utils';
import type { RiskLevel } from '@/types';
import { AlertTriangle, Shield, AlertCircle } from 'lucide-react';

interface RiskLevelBadgeProps {
  level: RiskLevel;
  size?: 'sm' | 'md' | 'lg';
  showText?: boolean;
}

const riskConfig = {
  high: {
    label: '高风险',
    bgClass: 'bg-danger-500',
    textClass: 'text-danger-500',
    lightBgClass: 'bg-danger-50',
    borderClass: 'border-danger-200',
    Icon: AlertTriangle,
  },
  medium: {
    label: '中风险',
    bgClass: 'bg-warning-500',
    textClass: 'text-warning-600',
    lightBgClass: 'bg-warning-50',
    borderClass: 'border-warning-200',
    Icon: AlertCircle,
  },
  low: {
    label: '低风险',
    bgClass: 'bg-safe-500',
    textClass: 'text-safe-600',
    lightBgClass: 'bg-safe-50',
    borderClass: 'border-safe-200',
    Icon: Shield,
  },
};

export default function RiskLevelBadge({ level, size = 'md', showText = true }: RiskLevelBadgeProps) {
  const config = riskConfig[level];
  const Icon = config.Icon;

  const sizeClasses = {
    sm: 'px-2 py-1 text-xs',
    md: 'px-3 py-1.5 text-sm',
    lg: 'px-4 py-2 text-base',
  };

  const iconSizes = {
    sm: 14,
    md: 18,
    lg: 24,
  };

  return (
    <span
      className={cn(
      'inline-flex items-center gap-1.5 rounded-full font-semibold',
      config.lightBgClass,
      config.textClass,
      sizeClasses[size]
    )}
    >
      <Icon size={iconSizes[size]} fill="currentColor" />
      {showText && config.label}
    </span>
  );
}
