export interface AnalysisResult {
  riskLevel: RiskLevel;
  riskTitle: string;
  riskDescription: string;
  matchedKeywords: string[];
  suggestions: string[];
}

export function analyzeContent(content: string): AnalysisResult {
  const text = content.toLowerCase();
  
  const matchedHigh = highRiskKeywords.filter(item => 
    text.includes(item.keyword.toLowerCase())
  );
  
  const matchedMedium = mediumRiskKeywords.filter(item => 
    text.includes(item.keyword.toLowerCase())
  );

  if (matchedHigh.length > 0) {
    const categories = [...new Set(matchedHigh.map(k => k.category))];
    const categoryText = categories.join('、');
    
    return {
      riskLevel: 'high',
      riskTitle: `高风险：疑似${categoryText}诈骗`,
      riskDescription: `检测到${matchedHigh.length}个高危特征：${matchedHigh.map(k => `"${k.keyword}"`).join('、')}。\n\n${matchedHigh[0].description}\n\n请立即停止操作，切勿转账或提供个人信息！`,
      matchedKeywords: matchedHigh.map(k => k.keyword),
      suggestions: [
        '立即挂断电话或退出聊天，不要继续与对方交流',
        '绝对不要转账、汇款，不要提供银行卡号和验证码',
        '拨打96110全国反诈专线咨询核实',
        '联系家人或子女，告诉他们发生了什么',
        '如果已经转账，立即拨打110报警',
      ],
    };
  }

  if (matchedMedium.length > 0) {
    const categories = [...new Set(matchedMedium.map(k => k.category))];
    const categoryText = categories.join('、');
    
    return {
      riskLevel: 'medium',
      riskTitle: `中等风险：${categoryText}需警惕`,
      riskDescription: `检测到${matchedMedium.length}个可疑特征：${matchedMedium.map(k => `"${k.keyword}"`).join('、')}。\n\n${matchedMedium[0].description}\n\n请谨慎对待，多方核实后再决定。`,
      matchedKeywords: matchedMedium.map(k => k.keyword),
      suggestions: [
        '不要急于做决定，先缓一缓',
        '和家人商量一下，听听他们的意见',
        '通过官方渠道核实信息真伪',
        '凡是涉及钱的事情，一定要多留心',
      ],
    };
  }

  return {
    riskLevel: 'low',
    riskTitle: '低风险：暂未发现明显诈骗特征',
    riskDescription: '根据您提供的内容，暂未检测到常见的诈骗关键词。\n\n但仍建议您保持警惕，遇到不确定的事情多和家人商量。',
    matchedKeywords: [],
    suggestions: [
      '继续保持警惕，遇到可疑情况及时核实',
      '不确定的时候，可以问问家人的意见',
      '平时多了解防诈知识，提高防范意识',
    ],
  };
}

export function generateRecordId(): string {
  return `record-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
}

export function createIdentifyRecord(
  type: IdentifyType,
  content: string,
  analysis: AnalysisResult
): IdentifyRecord {
  return {
    id: generateRecordId(),
    type,
    content,
    riskLevel: analysis.riskLevel,
    riskTitle: analysis.riskTitle,
    riskDescription: analysis.riskDescription,
    suggestions: analysis.suggestions,
    createdAt: new Date().toISOString(),
    notifiedFamily: analysis.riskLevel === 'high',
  };
}
