import { useState, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { Mic, Image, Type, Sparkles } from 'lucide-react';
import PageContainer from '@/components/layout/PageContainer';
import Card from '@/components/ui/Card';
import Button from '@/components/ui/Button';
import LoadingSpinner from '@/components/ui/LoadingSpinner';
import VoiceRecorder from '@/components/features/VoiceRecorder';
import ImageUploader from '@/components/features/ImageUploader';
import { useAppStore } from '@/store/useAppStore';
import { analyzeContent, createIdentifyRecord } from '@/utils/aiAnalyzer';
import { cn } from '@/lib/utils';

type IdentifyMode = 'voice' | 'image' | 'text';

export default function Identify() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { addRecord } = useAppStore();
  const [mode, setMode] = useState<IdentifyMode>('voice');
  const [textInput, setTextInput] = useState('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  useEffect(() => {
    const modeParam = searchParams.get('mode');
    if (modeParam === 'voice' || modeParam === 'image' || modeParam === 'text') {
      setMode(modeParam);
    }
  }, [searchParams]);

  const handleAnalyze = async (content: string, type: IdentifyMode) => {
    if (!content.trim()) return;

    setIsAnalyzing(true);

    await new Promise(resolve => setTimeout(resolve, 2000));

    const analysis = analyzeContent(content);
    const record = createIdentifyRecord(
      type === 'image' ? 'image' : type === 'voice' ? 'voice' : 'text',
      content,
      analysis
    );

    addRecord(record);
    setIsAnalyzing(false);
    navigate(`/result/${record.id}`);
  };

  const handleVoiceComplete = (text: string) => {
    handleAnalyze(text, 'voice');
  };

  const handleImageSelect = (imageUrl: string) => {
    const mockText = '这是一张短信截图，内容是：恭喜您中了大奖，需要先交5000元保证金才能领取奖品，请立即转账到安全账户，不要告诉家人。';
    handleAnalyze(mockText, 'image');
  };

  const handleTextSubmit = () => {
    handleAnalyze(textInput, 'text');
  };

  const quickExamples = [
    '接到公安局电话说我涉嫌洗钱',
    '收到中奖短信要先交手续费',
    '有人推荐高收益保本投资',
    '客服说订单异常要退款',
  ];

  if (isAnalyzing) {
    return (
      <PageContainer title="AI识别" showBack showBottomNav>
        <div className="flex flex-col items-center justify-center min-h-[60vh] px-4">
          <LoadingSpinner size="lg" text="AI正在分析中..." />
          <p className="mt-6 text-text-secondary text-center">
            请稍等，AI正在帮您识别诈骗风险
          </p>
        </div>
      </PageContainer>
    );
  }

  return (
    <PageContainer title="AI识别" showBack showBottomNav>
      {/* 模式切换 */}
      <div className="px-4 py-4">
        <div className="flex bg-gray-100 rounded-2xl p-1">
          {[
            { id: 'voice' as const, label: '语音', icon: Mic },
            { id: 'image' as const, label: '图片', icon: Image },
            { id: 'text' as const, label: '文字', icon: Type },
          ].map((item) => {
            const Icon = item.icon;
            const isActive = mode === item.id;
            return (
              <button
                key={item.id}
                onClick={() => setMode(item.id)}
                className={cn(
                  'flex-1 flex items-center justify-center gap-2 py-3 rounded-xl font-medium transition-all',
                  isActive
                    ? 'bg-white text-primary-500 shadow-card'
                    : 'text-text-secondary'
                )}
              >
                <Icon size={20} />
                {item.label}
              </button>
            );
          })}
        </div>
      </div>

      {/* 识别内容区 */}
      <div className="px-4 py-4">
        {mode === 'voice' && (
          <div className="animate-fade-in">
            <Card className="p-6">
              <div className="text-center mb-6">
                <div className="inline-flex items-center gap-2 px-4 py-2 bg-primary-50 rounded-full">
                  <Sparkles size={18} className="text-primary-500" />
                  <span className="text-sm font-medium text-primary-600">
                    AI智能识别
                  </span>
                </div>
                <h2 className="text-xl font-bold text-text-primary mt-4">
                  按住说话，描述您遇到的情况
                </h2>
                <p className="text-text-secondary mt-2">
                  比如："我接到一个电话，说我涉嫌犯罪..."
                </p>
              </div>
              <VoiceRecorder onRecordingComplete={handleVoiceComplete} />
            </Card>
          </div>
        )}

        {mode === 'image' && (
          <div className="animate-fade-in">
            <Card className="p-6">
              <div className="text-center mb-6">
                <div className="inline-flex items-center gap-2 px-4 py-2 bg-primary-50 rounded-full">
                  <Sparkles size={18} className="text-primary-500" />
                  <span className="text-sm font-medium text-primary-600">
                    AI智能识别
                  </span>
                </div>
                <h2 className="text-xl font-bold text-text-primary mt-4">
                  拍照或上传截图
                </h2>
                <p className="text-text-secondary mt-2">
                  支持短信截图、聊天记录、广告图片等
                </p>
              </div>
              <ImageUploader onImageSelect={handleImageSelect} />
            </Card>
          </div>
        )}

        {mode === 'text' && (
          <div className="animate-fade-in">
            <Card className="p-6">
              <div className="text-center mb-6">
                <div className="inline-flex items-center gap-2 px-4 py-2 bg-primary-50 rounded-full">
                  <Sparkles size={18} className="text-primary-500" />
                  <span className="text-sm font-medium text-primary-600">
                    AI智能识别
                  </span>
                </div>
                <h2 className="text-xl font-bold text-text-primary mt-4">
                  输入可疑内容
                </h2>
                <p className="text-text-secondary mt-2">
                  把您收到的短信、消息内容输入进来
                </p>
              </div>

              <textarea
                value={textInput}
                onChange={(e) => setTextInput(e.target.value)}
                placeholder="请输入您遇到的可疑内容，比如：您中奖了，请先交手续费..."
                className="w-full h-40 p-4 text-lg border-2 border-gray-200 rounded-2xl focus:border-primary-400 focus:outline-none resize-none bg-gray-50"
              />

              <div className="mt-4">
                <p className="text-sm text-text-tertiary mb-3">试试这些例子：</p>
                <div className="flex flex-wrap gap-2">
                  {quickExamples.map((example, index) => (
                    <button
                      key={index}
                      onClick={() => setTextInput(example)}
                      className="px-4 py-2 bg-gray-100 text-text-secondary rounded-full text-sm hover:bg-gray-200 transition-colors"
                    >
                      {example}
                    </button>
                  ))}
                </div>
              </div>

              <Button
                size="xl"
                fullWidth
                className="mt-6"
                onClick={handleTextSubmit}
                disabled={!textInput.trim()}
                icon={<Sparkles size={24} />}
              >
                开始分析
              </Button>
            </Card>
          </div>
        )}
      </div>

      {/* 底部提示 */}
      <div className="px-4 py-6">
        <div className="bg-warning-50 rounded-2xl p-4 flex items-start gap-3">
          <Sparkles size={20} className="text-warning-600 flex-shrink-0 mt-0.5" />
          <div>
            <p className="font-semibold text-warning-700">温馨提示</p>
            <p className="text-sm text-warning-600 mt-1">
              AI分析结果仅供参考，如果您觉得可疑，请立即停止操作并联系家人，或拨打96110咨询。
            </p>
          </div>
        </div>
      </div>
    </PageContainer>
  );
}
