import { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { 
  ChevronRight, 
  CheckCircle2, 
  XCircle, 
  Trophy,
  ArrowRight,
  RotateCcw
} from 'lucide-react';
import PageContainer from '@/components/layout/PageContainer';
import Card from '@/components/ui/Card';
import Button from '@/components/ui/Button';
import { mockScenarios } from '@/data/mockData';
import { cn } from '@/lib/utils';

export default function ScenarioDetail() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedOption, setSelectedOption] = useState<string | null>(null);
  const [showFeedback, setShowFeedback] = useState(false);
  const [score, setScore] = useState(0);
  const [isComplete, setIsComplete] = useState(false);

  const scenario = mockScenarios.find(s => s.id === id);

  if (!scenario) {
    return (
      <PageContainer title="情景训练" showBack showBottomNav>
        <div className="flex flex-col items-center justify-center min-h-[60vh] px-4">
          <p className="text-text-secondary text-lg">未找到该情景</p>
          <Button
            className="mt-6"
            onClick={() => navigate('/learn')}
          >
            返回学堂
          </Button>
        </div>
      </PageContainer>
    );
  }

  const currentQuestion = scenario.questions[currentQuestionIndex];
  const totalQuestions = scenario.questions.length;
  const progress = ((currentQuestionIndex + 1) / totalQuestions) * 100;

  const handleOptionSelect = (optionId: string) => {
    if (showFeedback) return;
    setSelectedOption(optionId);
    setShowFeedback(true);
    
    const selected = currentQuestion.options.find(o => o.id === optionId);
    if (selected?.isCorrect) {
      setScore(prev => prev + 10);
    }
  };

  const handleNext = () => {
    if (currentQuestionIndex < totalQuestions - 1) {
      setCurrentQuestionIndex(prev => prev + 1);
      setSelectedOption(null);
      setShowFeedback(false);
    } else {
      setIsComplete(true);
    }
  };

  const handleRestart = () => {
    setCurrentQuestionIndex(0);
    setSelectedOption(null);
    setShowFeedback(false);
    setScore(0);
    setIsComplete(false);
  };

  if (isComplete) {
    const perfectScore = totalQuestions * 10;
    const isPerfect = score === perfectScore;

    return (
      <PageContainer title="训练完成" showBack showBottomNav>
        <div className="px-4 py-8 text-center">
          <div className="relative inline-block mb-6">
            <div className="w-32 h-32 bg-warning-100 rounded-full flex items-center justify-center mx-auto">
              <Trophy size={64} className="text-warning-500" fill="#FFB800" />
            </div>
            <div className="absolute -top-2 -right-2 w-12 h-12 bg-safe-500 rounded-full flex items-center justify-center text-white font-bold">
              +{score}
            </div>
          </div>
          
          <h1 className="text-2xl font-bold text-text-primary mb-2">
            {isPerfect ? '太棒了！全部答对！' : '训练完成！'}
          </h1>
          <p className="text-text-secondary mb-8">
            您答对了 {score / 10}/{totalQuestions} 题，获得 {score} 积分
          </p>

          <Card className="p-5 mb-6 text-left">
            <h3 className="font-bold text-text-primary mb-4">学习总结</h3>
            <p className="text-text-secondary leading-relaxed">
              通过本次训练，您了解了{scenario.title}的常见套路。记住：凡是要求转账、索要验证码、让您保密的，都要提高警惕，多和家人商量。
            </p>
          </Card>

          <div className="flex gap-4">
            <Button
              variant="outline"
              size="lg"
              fullWidth
              icon={<RotateCcw size={20} />}
              onClick={handleRestart}
            >
              再来一次
            </Button>
            <Button
              size="lg"
              fullWidth
              onClick={() => navigate('/learn')}
            >
              返回学堂
            </Button>
          </div>
        </div>
      </PageContainer>
    );
  }

  return (
    <PageContainer title="情景训练" showBack showBottomNav>
      {/* 进度条 */}
      <div className="px-4 py-4">
        <div className="flex items-center justify-between mb-2">
          <span className="text-sm font-medium text-text-secondary">
            第 {currentQuestionIndex + 1}/{totalQuestions} 题
          </span>
          <span className="text-sm font-medium text-primary-500">
            +{score} 分
          </span>
        </div>
        <div className="h-2 bg-gray-100 rounded-full overflow-hidden">
          <div
            className="h-full bg-primary-500 rounded-full transition-all duration-300"
            style={{ width: `${progress}%` }}
          />
        </div>
      </div>

      {/* 情景描述 */}
      <div className="px-4 py-4">
        <Card className="p-5 bg-primary-50 border-2 border-primary-100">
          <div className="flex items-start gap-3">
            <span className="text-3xl">{scenario.image}</span>
            <div>
              <p className="font-bold text-primary-700 mb-1">
                情景：{scenario.title}
              </p>
              <p className="text-sm text-primary-600">
                {scenario.description}
              </p>
            </div>
          </div>
        </Card>
      </div>

      {/* 题目 */}
      <div className="px-4 py-4">
        <h2 className="text-lg font-bold text-text-primary mb-4">
          {currentQuestion.situation}
        </h2>

        <div className="space-y-3">
          {currentQuestion.options.map((option) => {
            const isSelected = selectedOption === option.id;
            const showCorrect = showFeedback && option.isCorrect;
            const showWrong = showFeedback && isSelected && !option.isCorrect;

            return (
              <button
                key={option.id}
                onClick={() => handleOptionSelect(option.id)}
                disabled={showFeedback}
                className={cn(
                  'w-full p-4 rounded-2xl text-left transition-all',
                  'border-2',
                  showCorrect
                    ? 'bg-safe-50 border-safe-400'
                    : showWrong
                    ? 'bg-danger-50 border-danger-400'
                    : isSelected
                    ? 'bg-primary-50 border-primary-400'
                    : 'bg-white border-gray-200 hover:border-primary-300'
                )}
              >
                <div className="flex items-start gap-3">
                  <div className={cn(
                    'w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 font-bold text-sm',
                    showCorrect
                      ? 'bg-safe-500 text-white'
                      : showWrong
                      ? 'bg-danger-500 text-white'
                      : isSelected
                      ? 'bg-primary-500 text-white'
                      : 'bg-gray-100 text-text-secondary'
                  )}>
                    {showCorrect ? (
                      <CheckCircle2 size={18} />
                    ) : showWrong ? (
                      <XCircle size={18} />
                    ) : (
                      option.id.toUpperCase()
                    )}
                  </div>
                  <p className={cn(
                    'flex-1 pt-1',
                    showCorrect ? 'text-safe-700 font-medium' :
                    showWrong ? 'text-danger-700' :
                    'text-text-primary'
                  )}>
                    {option.text}
                  </p>
                </div>
              </button>
            );
          })}
        </div>

        {/* 反馈信息 */}
        {showFeedback && selectedOption && (
          <div className={cn(
            'mt-6 p-4 rounded-2xl animate-fade-in',
            currentQuestion.options.find(o => o.id === selectedOption)?.isCorrect
              ? 'bg-safe-50 border-2 border-safe-200'
              : 'bg-warning-50 border-2 border-warning-200'
          )}>
            <p className="font-bold text-text-primary mb-2">
              {currentQuestion.options.find(o => o.id === selectedOption)?.isCorrect
                ? '✅ 回答正确！'
                : '💡 再想想哦'
              }
            </p>
            <p className="text-text-secondary leading-relaxed">
              {currentQuestion.options.find(o => o.id === selectedOption)?.feedback}
            </p>
          </div>
        )}
      </div>

      {/* 底部按钮 */}
      {showFeedback && (
        <div className="px-4 py-6">
          <Button
            size="xl"
            fullWidth
            icon={<ArrowRight size={24} />}
            onClick={handleNext}
          >
            {currentQuestionIndex < totalQuestions - 1 ? '下一题' : '查看结果'}
          </Button>
        </div>
      )}
    </PageContainer>
  );
}
