import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Phone, Mic, Image, AlertTriangle, GraduationCap, Volume2, ChevronRight, Shield, Clock, Sun, CloudRain } from 'lucide-react';
import PageContainer from '@/components/layout/PageContainer';
import Card from '@/components/ui/Card';
import RiskLevelBadge from '@/components/ui/RiskLevelBadge';
import { useAppStore } from '@/store/useAppStore';
import { mockTips } from '@/data/mockData';
import { getGreeting, formatDate, speak, stopSpeak } from '@/utils/helpers';

const featureItems = [
  {
    id: 'voice',
    icon: Mic,
    label: '语音问问',
    description: '说给AI听',
    color: 'bg-primary-500',
    bgColor: 'bg-primary-50',
    textColor: 'text-primary-500',
  },
  {
    id: 'image',
    icon: Image,
    label: '图片识别',
    description: '拍图上传',
    color: 'bg-info-500',
    bgColor: 'bg-info-50',
    textColor: 'text-info-500',
  },
  {
    id: 'report',
    icon: AlertTriangle,
    label: '一键举报',
    description: '举报诈骗',
    color: 'bg-warning-500',
    bgColor: 'bg-warning-50',
    textColor: 'text-warning-600',
  },
  {
    id: 'learn',
    icon: GraduationCap,
    label: '防诈学堂',
    description: '学知识',
    color: 'bg-safe-500',
    bgColor: 'bg-safe-50',
    textColor: 'text-safe-600',
  },
];

export default function Home() {
  const navigate = useNavigate();
  const { user, history } = useAppStore();
  const [currentTipIndex, setCurrentTipIndex] = useState(0);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [currentTime, setCurrentTime] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTime(new Date());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    const tipTimer = setInterval(() => {
      setCurrentTipIndex((prev) => (prev + 1) % mockTips.length);
    }, 5000);
    return () => clearInterval(tipTimer);
  }, []);

  const handleEmergencyCall = () => {
    window.location.href = 'tel:96110';
  };

  const handleFeatureClick = (id: string) => {
    switch (id) {
      case 'voice':
        navigate('/identify?mode=voice');
        break;
      case 'image':
        navigate('/identify?mode=image');
        break;
      case 'report':
        window.location.href = 'tel:96110';
        break;
      case 'learn':
        navigate('/learn');
        break;
    }
  };

  const handleSpeakTip = () => {
    if (isSpeaking) {
      stopSpeak();
      setIsSpeaking(false);
    } else {
      const tip = mockTips[currentTipIndex];
      speak(tip.title + '。' + tip.content);
      setIsSpeaking(true);
      setTimeout(() => setIsSpeaking(false), 5000);
    }
  };

  const recentHistory = history.slice(0, 3);

  const formatDateStr = (date: Date) => {
    const month = date.getMonth() + 1;
    const day = date.getDate();
    const weekDays = ['日', '一', '二', '三', '四', '五', '六'];
    const weekDay = weekDays[date.getDay()];
    return `${month}月${day}日 星期${weekDay}`;
  };

  return (
    <PageContainer showBottomNav>
      {/* 顶部问候区 */}
      <div className="px-4 pt-6 pb-4 bg-gradient-to-b from-primary-50 to-warm-50">
        <div className="flex items-start justify-between">
          <div>
            <p className="text-2xl font-bold text-text-primary">
              {getGreeting()}，{user.name}
            </p>
            <div className="flex items-center gap-3 mt-2">
              <div className="flex items-center gap-1 text-text-secondary">
                <Clock size={16} />
                <span className="text-sm">{formatDateStr(currentTime)}</span>
              </div>
              <div className="flex items-center gap-1 text-text-secondary">
                <Sun size={16} />
                <span className="text-sm">晴 26°C</span>
              </div>
            </div>
          </div>
          <div className="w-14 h-14 rounded-full bg-primary-100 flex items-center justify-center">
            <span className="text-2xl">👵</span>
          </div>
        </div>
      </div>

      {/* 紧急求助按钮 */}
      <div className="px-4 py-4">
        <button
          onClick={handleEmergencyCall}
          className="w-full relative overflow-hidden bg-gradient-to-r from-danger-500 to-danger-600 rounded-3xl p-6 text-white shadow-medium active:scale-[0.98] transition-transform"
        >
          <div className="absolute -right-4 -top-4 w-32 h-32 bg-white/10 rounded-full" />
          <div className="absolute -right-8 bottom-0 w-24 h-24 bg-white/10 rounded-full" />
          
          <div className="relative flex items-center gap-4">
            <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center animate-pulse-slow">
              <Shield size={36} fill="white" />
            </div>
            <div className="flex-1 text-left">
              <p className="text-xl font-bold mb-1">紧急求助</p>
              <p className="text-white/80 text-sm">遇到诈骗立即拨打96110</p>
            </div>
            <div className="bg-white/20 rounded-full p-2">
              <Phone size={24} />
            </div>
          </div>
        </button>
      </div>

      {/* 四大功能入口 */}
      <div className="px-4 py-2">
        <h2 className="text-lg font-bold text-text-primary mb-4">功能中心</h2>
        <div className="grid grid-cols-2 gap-4">
          {featureItems.map((item) => {
            const Icon = item.icon;
            return (
              <Card
                key={item.id}
                hover
                onClick={() => handleFeatureClick(item.id)}
                className="p-5"
              >
                <div className={`w-14 h-14 ${item.bgColor} rounded-2xl flex items-center justify-center mb-3`}>
                  <Icon size={28} className={item.textColor} />
                </div>
                <p className="text-lg font-bold text-text-primary">{item.label}</p>
                <p className="text-sm text-text-tertiary mt-1">{item.description}</p>
              </Card>
            );
          })}
        </div>
      </div>

      {/* 今日防诈贴士 */}
      <div className="px-4 py-4">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-lg font-bold text-text-primary">今日防诈贴士</h2>
          <button
            onClick={handleSpeakTip}
            className="flex items-center gap-1 text-primary-500 text-sm font-medium"
          >
            <Volume2 size={16} />
            {isSpeaking ? '停止' : '听一听'}
          </button>
        </div>
        
        <Card className="p-5 overflow-hidden">
          <div className="relative">
            {mockTips.map((tip, index) => (
              <div
                key={tip.id}
                className={`transition-all duration-500 ${
                  index === currentTipIndex
                    ? 'opacity-100 translate-x-0'
                    : 'opacity-0 absolute inset-0 translate-x-4'
                }`}
              >
                <div className="flex items-start gap-4">
                  <div className="text-4xl flex-shrink-0">{tip.icon}</div>
                  <div className="flex-1 min-w-0">
                    <p className="text-lg font-bold text-text-primary mb-2">
                      {tip.title}
                    </p>
                    <p className="text-text-secondary leading-relaxed">
                      {tip.content}
                    </p>
                  </div>
                </div>
              </div>
            ))}
          </div>
          
          <div className="flex justify-center gap-2 mt-4">
            {mockTips.map((_, index) => (
              <div
                key={index}
                className={`h-2 rounded-full transition-all duration-300 ${
                  index === currentTipIndex
                    ? 'w-6 bg-primary-500'
                    : 'w-2 bg-gray-200'
                }`}
              />
            ))}
          </div>
        </Card>
      </div>

      {/* 最近识别记录 */}
      {recentHistory.length > 0 && (
        <div className="px-4 py-4">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-lg font-bold text-text-primary">最近识别</h2>
            <button
              onClick={() => navigate('/profile')}
              className="flex items-center gap-1 text-text-tertiary text-sm"
            >
              查看全部
              <ChevronRight size={16} />
            </button>
          </div>
          
          <div className="space-y-3">
            {recentHistory.map((record) => (
              <Card
                key={record.id}
                hover
                onClick={() => navigate(`/result/${record.id}`)}
                className="p-4"
              >
                <div className="flex items-start justify-between gap-4">
                  <div className="flex-1 min-w-0">
                    <p className="text-base font-medium text-text-primary line-clamp-1">
                      {record.content.length > 30
                        ? record.content.slice(0, 30) + '...'
                        : record.content}
                    </p>
                    <p className="text-sm text-text-tertiary mt-1">
                      {formatDate(record.createdAt)}
                    </p>
                  </div>
                  <RiskLevelBadge level={record.riskLevel} size="sm" />
                </div>
              </Card>
            ))}
          </div>
        </div>
      )}

      {/* 底部安全提示 */}
      <div className="px-4 py-6">
        <div className="bg-safe-50 rounded-2xl p-4 flex items-start gap-3">
          <Shield size={24} className="text-safe-600 flex-shrink-0" />
          <div>
            <p className="font-semibold text-safe-700">银龄守护提醒您</p>
            <p className="text-sm text-safe-600 mt-1">
              遇事先问一问，转账先停一停。有疑问，找家人，或拨打96110。
            </p>
          </div>
        </div>
      </div>
    </PageContainer>
  );
}
