import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  GraduationCap, 
  BookOpen, 
  Gamepad2, 
  Trophy,
  ChevronRight,
  Star,
  Play
} from 'lucide-react';
import PageContainer from '@/components/layout/PageContainer';
import Card from '@/components/ui/Card';
import { mockScenarios, mockCases } from '@/data/mockData';
import { cn } from '@/lib/utils';

const difficultyConfig = {
  easy: { label: '简单', color: 'bg-safe-50 text-safe-600' },
  medium: { label: '中等', color: 'bg-warning-50 text-warning-600' },
  hard: { label: '困难', color: 'bg-danger-50 text-danger-600' },
};

export default function Learn() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<'scenario' | 'case'>('scenario');

  return (
    <PageContainer title="防诈学堂" showBottomNav>
      {/* 顶部banner */}
      <div className="px-4 pt-6 pb-4 bg-gradient-to-b from-safe-50 to-warm-50">
        <div className="flex items-center gap-4">
          <div className="w-16 h-16 bg-safe-100 rounded-2xl flex items-center justify-center">
            <GraduationCap size={32} className="text-safe-600" />
          </div>
          <div className="flex-1">
            <h2 className="text-xl font-bold text-text-primary">
              学习防诈知识
            </h2>
            <p className="text-sm text-text-secondary mt-1">
              每天学一点，防骗多一点
            </p>
          </div>
          <div className="text-right">
            <div className="flex items-center gap-1 text-warning-500">
              <Trophy size={20} />
              <span className="font-bold">120</span>
            </div>
            <p className="text-xs text-text-tertiary">积分</p>
          </div>
        </div>
      </div>

      {/* Tab切换 */}
      <div className="px-4 py-4">
        <div className="flex bg-gray-100 rounded-2xl p-1">
          {[
            { id: 'scenario' as const, label: '情景模拟', icon: Gamepad2 },
            { id: 'case' as const, label: '真实案例', icon: BookOpen },
          ].map((tab) => {
            const Icon = tab.icon;
            const isActive = activeTab === tab.id;
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={cn(
                  'flex-1 flex items-center justify-center gap-2 py-3 rounded-xl font-medium transition-all',
                  isActive
                    ? 'bg-white text-safe-600 shadow-card'
                    : 'text-text-secondary'
                )}
              >
                <Icon size={20} />
                {tab.label}
              </button>
            );
          })}
        </div>
      </div>

      {/* 情景模拟 */}
      {activeTab === 'scenario' && (
        <div className="px-4 pb-4">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-lg font-bold text-text-primary">情景训练</h2>
            <span className="text-sm text-text-tertiary">
              完成可获得积分奖励
            </span>
          </div>

          <div className="space-y-4">
            {mockScenarios.map((scenario) => {
              const diffConfig = difficultyConfig[scenario.difficulty];
              return (
                <Card
                  key={scenario.id}
                  hover
                  onClick={() => navigate(`/learn/scenario/${scenario.id}`)}
                  className="p-5"
                >
                  <div className="flex items-start gap-4">
                    <div className="w-16 h-16 bg-primary-50 rounded-2xl flex items-center justify-center text-3xl flex-shrink-0">
                      {scenario.image}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <h3 className="font-bold text-text-primary text-lg">
                          {scenario.title}
                        </h3>
                        <span className={cn(
                          'px-2 py-0.5 text-xs rounded-full font-medium',
                          diffConfig.color
                        )}>
                          {diffConfig.label}
                        </span>
                      </div>
                      <p className="text-sm text-text-secondary mt-1 line-clamp-2">
                        {scenario.description}
                      </p>
                      <div className="flex items-center justify-between mt-3">
                        <div className="flex items-center gap-1 text-warning-500">
                          <Star size={16} fill="currentColor" />
                          <span className="text-sm font-medium">
                            +{scenario.questions.length * 10}积分
                          </span>
                        </div>
                        <button className="flex items-center gap-1 text-safe-600 text-sm font-medium">
                          <Play size={16} />
                          开始挑战
                        </button>
                      </div>
                    </div>
                  </div>
                </Card>
              );
            })}
          </div>
        </div>
      )}

      {/* 真实案例 */}
      {activeTab === 'case' && (
        <div className="px-4 pb-4">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-lg font-bold text-text-primary">真实案例</h2>
            <span className="text-sm text-text-tertiary">
              以案为鉴，远离诈骗</span>
          </div>

          <div className="space-y-3">
            {mockCases.map((caseItem) => (
              <Card key={caseItem.id} hover className="p-4">
                <div className="flex items-start gap-4">
                  <div className="w-14 h-14 bg-warning-50 rounded-xl flex items-center justify-center text-2xl flex-shrink-0">
                    {caseItem.image}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <h3 className="font-bold text-text-primary">
                        {caseItem.title}
                      </h3>
                      {caseItem.read && (
                        <span className="text-xs text-text-tertiary">已读</span>
                      )}
                    </div>
                    <p className="text-sm text-text-secondary mt-1 line-clamp-2">
                      {caseItem.description}
                    </p>
                    <div className="flex items-center justify-between mt-3">
                      <span className="px-2 py-0.5 bg-primary-50 text-primary-600 text-xs rounded-full">
                        {caseItem.type}
                      </span>
                      <ChevronRight size={18} className="text-text-tertiary" />
                    </div>
                  </div>
                </div>
              </Card>
            ))}
          </div>
        </div>
      )}

      {/* 每日答题 */}
      <div className="px-4 py-4 pb-8">
        <Card className="p-5 bg-gradient-to-br from-warning-50 to-warm-50 overflow-hidden relative">
          <div className="absolute -right-4 -bottom-4 w-24 h-24 bg-warning-100/50 rounded-full" />
          <div className="relative flex items-center gap-4">
            <div className="w-14 h-14 bg-white rounded-2xl flex items-center justify-center shadow-card">
              <span className="text-3xl">❓</span>
            </div>
            <div className="flex-1">
              <p className="font-bold text-text-primary text-lg">每日一答</p>
              <p className="text-sm text-text-secondary mt-1">
                答对获得额外积分奖励
              </p>
            </div>
            <button className="px-5 py-2.5 bg-warning-500 text-white rounded-xl font-medium shadow-soft">
              去答题
            </button>
          </div>
        </Card>
      </div>
    </PageContainer>
  );
}
