import { useState, useRef, useCallback, useEffect } from 'react';
import { Mic, MicOff, Square, Play, Volume2 } from 'lucide-react';
import { cn } from '@/lib/utils';

interface VoiceRecorderProps {
  onRecordingComplete?: (text: string) => void;
  className?: string;
}

export default function VoiceRecorder({ onRecordingComplete, className }: VoiceRecorderProps) {
  const [isRecording, setIsRecording] = useState(false);
  const [recordedText, setRecordedText] = useState('');
  const [isSupported, setIsSupported] = useState(true);
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    if ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window) {
      setIsSupported(true);
    } else {
      setIsSupported(false);
    }
  }, []);

  const startRecording = useCallback(() => {
    if (!isSupported) return;

    const SpeechRecognition = (window as any).webkitSpeechRecognition || (window as any).SpeechRecognition;
    const recognition = new SpeechRecognition();
    
    recognition.lang = 'zh-CN';
    recognition.continuous = true;
    recognition.interimResults = true;

    recognition.onresult = (event: any) => {
      let transcript = '';
      for (let i = event.resultIndex; i < event.results.length; i++) {
        transcript += event.results[i][0].transcript;
      }
      setRecordedText(transcript);
    };

    recognition.onerror = (event: any) => {
      console.error('语音识别错误:', event.error);
      setIsRecording(false);
    };

    recognition.onend = () => {
      setIsRecording(false);
    };

    recognitionRef.current = recognition;
    recognition.start();
    setIsRecording(true);
    setRecordedText('');
  }, [isSupported]);

  const stopRecording = useCallback(() => {
    if (recognitionRef.current) {
      recognitionRef.current.stop();
      setIsRecording(false);
      if (recordedText && onRecordingComplete) {
        onRecordingComplete(recordedText);
      }
    }
  }, [recordedText, onRecordingComplete]);

  const handleButtonClick = () => {
    if (isRecording) {
      stopRecording();
    } else {
      startRecording();
    }
  };

  const speakDemo = () => {
    const demoText = '我刚才接到一个电话，对方说自己是公安局的，说我涉嫌洗钱，让我把钱转到安全账户';
    setRecordedText(demoText);
    if (onRecordingComplete) {
      onRecordingComplete(demoText);
    }
  };

  if (!isSupported) {
    return (
      <div className={cn('text-center py-8', className)}>
        <div className="w-20 h-20 mx-auto mb-4 rounded-full bg-gray-100 flex items-center justify-center">
          <MicOff size={32} className="text-gray-400" />
        </div>
        <p className="text-text-secondary mb-2">当前浏览器不支持语音识别</p>
        <p className="text-sm text-text-tertiary">您可以使用文字输入功能</p>
        <button
          onClick={speakDemo}
          className="mt-4 px-6 py-2 bg-primary-50 text-primary-600 rounded-full text-sm font-medium"
        >
          体验示例
        </button>
      </div>
    );
  }

  return (
    <div className={cn('flex flex-col items-center', className)}>
      <button
        onClick={handleButtonClick}
        className={cn(
          'relative w-28 h-28 rounded-full flex items-center justify-center transition-all duration-300',
          isRecording
            ? 'bg-danger-500 scale-110'
            : 'bg-primary-500 hover:bg-primary-600 active:scale-95'
        )}
      >
        {isRecording && (
          <>
            <span className="absolute inset-0 rounded-full bg-danger-500 animate-ping opacity-30" />
            <span className="absolute inset-2 rounded-full bg-danger-400 animate-pulse opacity-50" />
          </>
        )}
        {isRecording ? (
          <Square size={40} className="text-white relative z-10" fill="white" />
        ) : (
          <Mic size={48} className="text-white relative z-10" />
        )}
      </button>
      
      <p className="mt-4 text-lg font-medium text-text-primary">
        {isRecording ? '正在聆听...' : '点击说话'}
      </p>
      <p className="text-sm text-text-tertiary mt-1">
        {isRecording ? '再次点击结束录音' : '请用普通话描述您遇到的情况'}
      </p>

      {recordedText && (
        <div className="mt-6 w-full bg-white rounded-2xl p-4 shadow-card">
          <div className="flex items-center gap-2 mb-2">
            <Volume2 size={18} className="text-primary-500" />
            <span className="text-sm font-medium text-text-secondary">识别结果</span>
          </div>
          <p className="text-text-primary leading-relaxed">{recordedText}</p>
          {!isRecording && recordedText && (
            <div className="mt-4 flex gap-3">
              <button
                onClick={() => setRecordedText('')}
                className="flex-1 py-3 bg-gray-100 text-text-secondary rounded-xl font-medium"
              >
                重新录
              </button>
              <button
                onClick={() => onRecordingComplete && onRecordingComplete(recordedText)}
                className="flex-1 py-3 bg-primary-500 text-white rounded-xl font-medium"
              >
                开始分析
              </button>
            </div>
          )}
        </div>
      )}

      {!isRecording && !recordedText && (
        <button
          onClick={speakDemo}
          className="mt-6 px-5 py-2 bg-primary-50 text-primary-600 rounded-full text-sm font-medium flex items-center gap-2"
        >
          <Play size={16} />
          听个例子试试
        </button>
      )}
    </div>
  );
}
