import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { 
  AlertTriangle, 
  Shield, 
  AlertCircle, 
  Phone, 
  Users, 
  CheckCircle2,
  Volume2,
  Home,
  ChevronRight
} from 'lucide-react';
import PageContainer from '@/components/layout/PageContainer';
import Card from '@/components/ui/Card';
import Button from '@/components/ui/Button';
import RiskLevelBadge from '@/components/ui/RiskLevelBadge';
import { useAppStore } from '@/store/useAppStore';
import { formatDateTime, speak, stopSpeak } from '@/utils/helpers';
import { cn } from '@/lib/utils';

export default function Result() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { getRecordById, guardians } = useAppStore();
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [showAnimated, setShowAnimated] = useState(false);

  const record = getRecordById(id || '');

  useEffect(() => {
    const timer = setTimeout(() => {
      setShowAnimated(true);
    }, 100);
    return () => clearTimeout(timer);
  }, []);

  if (!record) {
    return (
      <PageContainer title="识别结果" showBack showBottomNav>
        <div className="flex flex-col items-center justify-center min-h-[60vh] px-4">
          <p className="text-text-secondary text-lg">未找到该记录</p>
          <Button
            className="mt-6"
            onClick={() => navigate('/')}
            icon={<Home size={20} />}
          >
            返回首页
          </Button>
        </div>
      </PageContainer>
    );
  }

  const riskConfig = {
    high: {
      icon: AlertTriangle,
      iconBg: 'bg-danger-500',
      iconRing: 'ring-danger-200',
      titleColor: 'text-danger-600',
      bgGradient: 'from-danger-50 to-white',
      borderColor: 'border-danger-200',
      buttonVariant: 'danger' as const,
    },
    medium: {
      icon: AlertCircle,
      iconBg: 'bg-warning-500',
      iconRing: 'ring-warning-200',
      titleColor: 'text-warning-600',
      bgGradient: 'from-warning-50 to-white',
      borderColor: 'border-warning-200',
      buttonVariant: 'primary' as const,
    },
    low: {
      icon: Shield,
      iconBg: 'bg-safe-500',
      iconRing: 'ring-safe-200',
      titleColor: 'text-safe-600',
      bgGradient: 'from-safe-50 to-white',
      borderColor: 'border-safe-200',
      buttonVariant: 'safe' as const,
    },
  };

  const config = riskConfig[record.riskLevel];
  const Icon = config.icon;

  const handleSpeak = () => {
    if (isSpeaking) {
      stopSpeak();
      setIsSpeaking(false);
    } else {
      const text = `${record.riskTitle}。${record.riskDescription}。建议：${record.suggestions.join('。')}`;
      speak(text);
      setIsSpeaking(true);
      setTimeout(() => setIsSpeaking(false), 15000);
    }
  };

  const handleCall96110 = () => {
    window.location.href = 'tel:96110';
  };

  const handleCallFamily = () => {
    if (guardians.length > 0) {
      window.location.href = `tel:${guardians[0].phone.replace(/\*/g, '')}`;
    }
  };

  return (
    <PageContainer title="识别结果" showBack showBottomNav>
      {/* 风险等级展示 */}
      <div className={cn(
        'px-4 pt-8 pb-6 text-center bg-gradient-to-b',
        config.bgGradient,
        showAnimated ? 'animate-fade-in' : 'opacity-0'
      )}>
        <div className="relative inline-block">
          <div className={cn(
            'w-32 h-32 rounded-full flex items-center justify-center',
            config.iconBg,
            'ring-8',
            config.iconRing,
            'mx-auto',
            showAnimated ? 'animate-scale-in' : ''
          )}>
            <Icon size={64} className="text-white" fill="white" />
          </div>
          {record.riskLevel === 'high' && (
            <div className="absolute inset-0 rounded-full animate-ping bg-danger-500/30" />
          )}
        </div>
        
        <h1 className={cn('text-2xl font-bold mt-6', config.titleColor)}>
          {record.riskTitle}
        </h1>
        
        <div className="flex items-center justify-center gap-4 mt-4">
          <RiskLevelBadge level={record.riskLevel} size="md" />
          <button
            onClick={handleSpeak}
            className="flex items-center gap-2 px-4 py-2 bg-white rounded-full shadow-card text-text-secondary text-sm"
          >
            <Volume2 size={18} className={isSpeaking ? 'text-primary-500' : ''} />
            {isSpeaking ? '播放中' : '听一听'}
          </button>
        </div>
      </div>

      {/* 风险说明 */}
      <div className="px-4 py-4">
        <Card className={cn('p-5 border-2', config.borderColor)}>
          <h2 className="text-lg font-bold text-text-primary mb-3">风险分析</h2>
          <p className="text-text-secondary leading-relaxed whitespace-pre-line">
            {record.riskDescription}
          </p>
          
          <div className="mt-4 pt-4 border-t border-gray-100">
            <p className="text-sm text-text-tertiary">
              识别时间：{formatDateTime(record.createdAt)}
            </p>
            {record.notifiedFamily && (
              <p className="text-sm text-primary-500 mt-1 flex items-center gap-1">
                <Users size={14} />
                已自动通知亲情守护人
              </p>
            )}
          </div>
        </Card>
      </div>

      {/* 处理建议 */}
      <div className="px-4 py-4">
        <h2 className="text-lg font-bold text-text-primary mb-4">处理建议</h2>
        <div className="space-y-3">
          {record.suggestions.map((suggestion, index) => (
            <Card key={index} className="p-4">
              <div className="flex items-start gap-4">
                <div className={cn(
                  'w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 text-white font-bold text-sm',
                  config.iconBg
                )}>
                  {index + 1}
                </div>
                <p className="text-text-primary leading-relaxed pt-1">
                  {suggestion}
                </p>
              </div>
            </Card>
          ))}
        </div>
      </div>

      {/* 一键求助 */}
      {record.riskLevel !== 'low' && (
        <div className="px-4 py-4">
          <h2 className="text-lg font-bold text-text-primary mb-4">一键求助</h2>
          <div className="grid grid-cols-2 gap-4">
            <Button
              variant="danger"
              size="lg"
              icon={<Phone size={24} />}
              onClick={handleCall96110}
            >
              拨打96110
            </Button>
            <Button
              variant="primary"
              size="lg"
              icon={<Users size={24} />}
              onClick={handleCallFamily}
            >
              联系家人
            </Button>
          </div>
        </div>
      )}

      {/* 已完成提醒 */}
      {record.riskLevel === 'low' && (
        <div className="px-4 py-4">
          <Card className="p-5 bg-safe-50 border-2 border-safe-200">
            <div className="flex items-start gap-4">
              <CheckCircle2 size={32} className="text-safe-500 flex-shrink-0" />
              <div>
                <p className="font-bold text-safe-700">暂时安全</p>
                <p className="text-sm text-safe-600 mt-1">
                  根据您提供的内容，暂未发现明显诈骗特征。但仍建议您保持警惕，遇到不确定的事情多和家人商量。
                </p>
              </div>
            </div>
          </Card>
        </div>
      )}

      {/* 底部操作 */}
      <div className="px-4 py-6">
        <Button
          variant="outline"
          size="lg"
          fullWidth
          icon={<Home size={20} />}
          onClick={() => navigate('/')}
        >
          返回首页
        </Button>
      </div>
    </PageContainer>
  );
}
