import { Shield } from 'lucide-react';

interface LoadingSpinnerProps {
  text?: string;
  size?: 'sm' | 'md' | 'lg';
}

export default function LoadingSpinner({ text = 'AI正在分析中...', size = 'md' }: LoadingSpinnerProps) {
  const sizeClasses = {
    sm: 'w-8 h-8',
    md: 'w-16 h-16',
    lg: 'w-24 h-24',
  };

  return (
    <div className="flex flex-col items-center justify-center py-8">
      <div className="relative">
        <div className={[
          sizeClasses[size],
          'rounded-full border-4 border-primary-100 border-t-primary-500 animate-spin',
        ].join(' ')} />
        <div className="absolute inset-0 flex items-center justify-center">
          <Shield 
            size={size === 'lg' ? 32 : size === 'md' ? 20 : 12} 
            className="text-primary-500" 
          />
        </div>
      </div>
      {text && (
        <p className="mt-4 text-text-secondary font-medium animate-pulse">
          {text}
        </p>
      )}
    </div>
  );
}
