import { ReactNode } from 'react';
import { ChevronLeft } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { cn } from '@/lib/utils';

interface PageContainerProps {
  children: ReactNode;
  title?: string;
  showBack?: boolean;
  showBottomNav?: boolean;
  className?: string;
}

export default function PageContainer({
  children,
  title,
  showBack = false,
  showBottomNav = true,
  className,
}: PageContainerProps) {
  const navigate = useNavigate();

  return (
    <div className="min-h-screen bg-warm-50">
      {title && (
        <header className="sticky top-0 z-40 bg-white/80 backdrop-blur-md border-b border-gray-100 safe-area-top">
          <div className="flex items-center h-14 px-4 max-w-lg mx-auto">
            {showBack && (
              <button
                onClick={() => navigate(-1)}
                className="p-2 -ml-2 rounded-full hover:bg-gray-100 transition-colors"
                aria-label="返回"
              >
                <ChevronLeft size={24} className="text-text-primary" />
              </button>
            )}
            <h1 className="text-lg font-semibold text-text-primary flex-1 text-center">
              {title}
            </h1>
            {showBack && <div className="w-10" />}
          </div>
        </header>
      )}
      
      <main className={cn(
        'max-w-lg mx-auto pb-4',
        showBottomNav ? 'pb-24' : 'pb-8',
        className
      )}>
        {children}
      </main>
    </div>
  );
}
