import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  Shield, 
  Users, 
  Bell, 
  Plus, 
  Phone, 
  MoreHorizontal,
  Copy,
  Check,
  Clock,
  ChevronRight
} from 'lucide-react';
import PageContainer from '@/components/layout/PageContainer';
import Card from '@/components/ui/Card';
import Button from '@/components/ui/Button';
import RiskLevelBadge from '@/components/ui/RiskLevelBadge';
import { useAppStore } from '@/store/useAppStore';
import { copyToClipboard, formatDate } from '@/utils/helpers';

export default function Family() {
  const navigate = useNavigate();
  const { guardians, history } = useAppStore();
  const [copied, setCopied] = useState(false);

  const inviteCode = 'YL8888';

  const handleCopyCode = async () => {
    const success = await copyToClipboard(inviteCode);
    if (success) {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const notifications = history
    .filter(h => h.riskLevel === 'high')
    .slice(0, 5)
    .map(record => ({
      id: record.id,
      guardianName: guardians[0]?.name || '家人',
      riskLevel: record.riskLevel,
      riskTitle: record.riskTitle,
      notifiedAt: record.createdAt,
      status: 'sent' as const,
    }));

  return (
    <PageContainer title="亲情守护" showBottomNav>
      {/* 顶部横幅 */}
      <div className="px-4 pt-6 pb-4 bg-gradient-to-b from-primary-50 to-warm-50">
        <div className="flex items-center gap-4">
          <div className="w-16 h-16 bg-primary-100 rounded-2xl flex items-center justify-center">
            <Users size={32} className="text-primary-500" />
          </div>
          <div className="flex-1">
            <h2 className="text-xl font-bold text-text-primary">
              家人守护您的安全
            </h2>
            <p className="text-sm text-text-secondary mt-1">
              绑定家人，高风险时自动提醒
            </p>
          </div>
        </div>
      </div>

      {/* 已绑定家人 */}
      <div className="px-4 py-4">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-lg font-bold text-text-primary">
            守护人 ({guardians.length})
          </h2>
          <button className="flex items-center gap-1 text-primary-500 text-sm font-medium">
            <Plus size={18} />
            添加
          </button>
        </div>

        <div className="space-y-3">
          {guardians.map((guardian) => (
            <Card key={guardian.id} className="p-4">
              <div className="flex items-center gap-4">
                <div className="relative">
                  <div className="w-14 h-14 bg-primary-100 rounded-full flex items-center justify-center text-2xl">
                    {guardian.relation === '儿子' ? '👨' : '👩'}
                  </div>
                  {guardian.isOnline && (
                    <div className="absolute bottom-0 right-0 w-4 h-4 bg-safe-500 rounded-full border-2 border-white" />
                  )}
                </div>
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <p className="font-bold text-text-primary text-lg">
                      {guardian.name}
                    </p>
                    <span className="px-2 py-0.5 bg-primary-50 text-primary-600 text-xs rounded-full">
                      {guardian.relation}
                    </span>
                  </div>
                  <p className="text-sm text-text-tertiary mt-1">
                    {guardian.phone}
                  </p>
                </div>
                <button
                  onClick={() => window.location.href = `tel:${guardian.phone.replace(/\*/g, '')}`}
                  className="w-12 h-12 bg-safe-50 rounded-full flex items-center justify-center"
                >
                  <Phone size={24} className="text-safe-500" />
                </button>
              </div>
            </Card>
          ))}
        </div>
      </div>

      {/* 邀请家人 */}
      <div className="px-4 py-4">
        <Card className="p-5 bg-gradient-to-br from-primary-50 to-warm-50">
          <div className="flex items-start justify-between mb-4">
            <div>
              <h3 className="text-lg font-bold text-text-primary">邀请家人加入</h3>
              <p className="text-sm text-text-secondary mt-1">
                让子女下载APP，扫码或输入邀请码绑定
              </p>
            </div>
            <Shield size={32} className="text-primary-400" />
          </div>
          
          {/* 模拟二维码 */}
          <div className="bg-white rounded-2xl p-6 flex flex-col items-center">
            <div className="w-32 h-32 bg-gray-100 rounded-xl flex items-center justify-center mb-4 border-2 border-dashed border-gray-300">
              <span className="text-4xl">📱</span>
            </div>
            <p className="text-sm text-text-tertiary mb-2">扫一扫绑定</p>
            
            <div className="w-full mt-4">
              <p className="text-sm text-text-secondary text-center mb-2">或输入邀请码</p>
              <div className="flex items-center gap-2">
                <div className="flex-1 bg-gray-50 rounded-xl px-4 py-3 text-center">
                  <span className="text-2xl font-bold tracking-widest text-primary-500">
                    {inviteCode}
                  </span>
                </div>
                <button
                  onClick={handleCopyCode}
                  className="flex items-center gap-1 px-4 py-3 bg-primary-500 text-white rounded-xl font-medium"
                >
                  {copied ? <Check size={20} /> : <Copy size={20} />}
                  {copied ? '已复制' : '复制'}
                </button>
              </div>
            </div>
          </div>
        </Card>
      </div>

      {/* 风险提醒记录 */}
      <div className="px-4 py-4">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-lg font-bold text-text-primary">风险提醒记录</h2>
          <button className="text-sm text-text-tertiary flex items-center gap-1">
            全部
            <ChevronRight size={16} />
          </button>
        </div>

        {notifications.length > 0 ? (
          <div className="space-y-3">
            {notifications.map((notification) => (
              <Card key={notification.id} className="p-4">
                <div className="flex items-start gap-4">
                  <div className="w-10 h-10 bg-danger-50 rounded-full flex items-center justify-center flex-shrink-0">
                    <Bell size={20} className="text-danger-500" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-start justify-between gap-2">
                      <p className="font-medium text-text-primary">
                        已通知 {notification.guardianName}
                      </p>
                      <RiskLevelBadge level={notification.riskLevel} size="sm" />
                    </div>
                    <p className="text-sm text-text-secondary mt-1 line-clamp-1">
                      {notification.riskTitle}
                    </p>
                    <div className="flex items-center gap-1 mt-2 text-xs text-text-tertiary">
                      <Clock size={14} />
                      {formatDate(notification.notifiedAt)}
                    </div>
                  </div>
                </div>
              </Card>
            ))}
          </div>
        ) : (
          <Card className="p-8 text-center">
            <div className="w-16 h-16 mx-auto bg-safe-50 rounded-full flex items-center justify-center mb-4">
              <Shield size={32} className="text-safe-500" />
            </div>
            <p className="text-text-secondary">暂无风险提醒</p>
            <p className="text-sm text-text-tertiary mt-1">
              遇到高风险情况会自动通知家人
            </p>
          </Card>
        )}
      </div>

      {/* 守护设置 */}
      <div className="px-4 py-4 pb-8">
        <h2 className="text-lg font-bold text-text-primary mb-4">守护设置</h2>
        <Card className="overflow-hidden">
          {[
            { label: '高风险自动通知家人', desc: '检测到高风险时自动发送提醒', value: true },
            { label: '每日安全报告', desc: '每天发送防诈小贴士', value: true },
            { label: '识别记录共享', desc: '家人可查看识别历史', value: false },
          ].map((item, index) => (
            <div
              key={index}
              className="flex items-center justify-between p-4 border-b border-gray-50 last:border-0"
            >
              <div className="flex-1">
                <p className="font-medium text-text-primary">{item.label}</p>
                <p className="text-sm text-text-tertiary mt-1">{item.desc}</p>
              </div>
              <div className={`w-12 h-7 rounded-full transition-colors relative ${
                item.value ? 'bg-primary-500' : 'bg-gray-200'
              }`}>
                <div className={`absolute top-1 w-5 h-5 bg-white rounded-full shadow transition-transform ${
                  item.value ? 'translate-x-6' : 'translate-x-1'
                }`} />
              </div>
            </div>
          ))}
        </Card>
      </div>
    </PageContainer>
  );
}
