import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import type { UserProfile, UserSettings, IdentifyRecord, FamilyGuardian, FontSize } from '@/types';

interface AppState {
  user: UserProfile;
  history: IdentifyRecord[];
  guardians: FamilyGuardian[];
  updateUser: (user: Partial<UserProfile>) => void;
  updateSettings: (settings: Partial<UserSettings>) => void;
  setFontSize: (size: FontSize) => void;
  addRecord: (record: IdentifyRecord) => void;
  getRecordById: (id: string) => IdentifyRecord | undefined;
  addGuardian: (guardian: FamilyGuardian) => void;
  removeGuardian: (id: string) => void;
}

const defaultSettings: UserSettings = {
  fontSize: 'normal',
  voiceBroadcast: true,
  darkMode: false,
  familyNotification: true,
};

const defaultUser: UserProfile = {
  id: 'user-001',
  name: '李奶奶',
  phone: '138****8888',
  avatar: '',
  settings: defaultSettings,
};

const defaultGuardians: FamilyGuardian[] = [
  {
    id: 'guardian-001',
    name: '小明',
    relation: '儿子',
    phone: '139****9999',
    avatar: '',
    isOnline: true,
    bindDate: '2024-01-15',
  },
  {
    id: 'guardian-002',
    name: '小红',
    relation: '女儿',
    phone: '137****7777',
    avatar: '',
    isOnline: false,
    bindDate: '2024-02-20',
  },
];

export const useAppStore = create<AppState>()(
  persist(
    (set, get) => ({
      user: defaultUser,
      history: [],
      guardians: defaultGuardians,

      updateUser: (user) =>
        set((state) => ({
          user: { ...state.user, ...user },
        })),

      updateSettings: (settings) =>
        set((state) => ({
          user: {
            ...state.user,
            settings: { ...state.user.settings, ...settings },
          },
        })),

      setFontSize: (size) =>
        set((state) => ({
          user: {
            ...state.user,
            settings: { ...state.user.settings, fontSize: size },
          },
        })),

      addRecord: (record) =>
        set((state) => ({
          history: [record, ...state.history],
        })),

      getRecordById: (id) => {
        return get().history.find((r) => r.id === id);
      },

      addGuardian: (guardian) =>
        set((state) => ({
          guardians: [...state.guardians, guardian],
        })),

      removeGuardian: (id) =>
        set((state) => ({
          guardians: state.guardians.filter((g) => g.id !== id),
        })),
    }),
    {
      name: 'yinling-shouhu-store',
    }
  )
);
