import { useRef, useState } from 'react';
import { Camera, Image, Upload, X } from 'lucide-react';
import { cn } from '@/lib/utils';

interface ImageUploaderProps {
  onImageSelect?: (imageUrl: string) => void;
  className?: string;
}

export default function ImageUploader({ onImageSelect, className }: ImageUploaderProps) {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);
  const [previewImage, setPreviewImage] = useState<string | null>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        const result = event.target?.result as string;
        setPreviewImage(result);
        if (onImageSelect) {
          onImageSelect(result);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleCameraClick = () => {
    cameraInputRef.current?.click();
  };

  const handleGalleryClick = () => {
    fileInputRef.current?.click();
  };

  const clearImage = () => {
    setPreviewImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
    if (cameraInputRef.current) cameraInputRef.current.value = '';
  };

  if (previewImage) {
    return (
      <div className={cn('relative', className)}>
        <div className="relative rounded-2xl overflow-hidden shadow-card">
          <img
            src={previewImage}
            alt="预览"
            className="w-full h-64 object-cover"
          />
          <button
            onClick={clearImage}
            className="absolute top-3 right-3 w-10 h-10 bg-black/50 rounded-full flex items-center justify-center"
          >
            <X size={20} className="text-white" />
          </button>
        </div>
        <div className="mt-4 flex gap-3">
          <button
            onClick={clearImage}
            className="flex-1 py-3 bg-gray-100 text-text-secondary rounded-xl font-medium"
          >
            重新选择
          </button>
          <button
            onClick={() => onImageSelect && onImageSelect(previewImage)}
            className="flex-1 py-3 bg-primary-500 text-white rounded-xl font-medium"
          >
            开始分析
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className={cn('space-y-4', className)}>
      <input
        ref={fileInputRef}
        type="file"
        accept="image/*"
        onChange={handleFileChange}
        className="hidden"
      />
      <input
        ref={cameraInputRef}
        type="file"
        accept="image/*"
        capture="environment"
        onChange={handleFileChange}
        className="hidden"
      />

      <div className="grid grid-cols-2 gap-4">
        <button
          onClick={handleCameraClick}
          className="flex flex-col items-center justify-center p-6 bg-white rounded-2xl shadow-card hover:shadow-medium transition-shadow active:scale-[0.98]"
        >
          <div className="w-16 h-16 rounded-full bg-primary-50 flex items-center justify-center mb-3">
            <Camera size={32} className="text-primary-500" />
          </div>
          <span className="text-lg font-semibold text-text-primary">拍照识别</span>
          <span className="text-sm text-text-tertiary mt-1">拍摄可疑内容</span>
        </button>

        <button
          onClick={handleGalleryClick}
          className="flex flex-col items-center justify-center p-6 bg-white rounded-2xl shadow-card hover:shadow-medium transition-shadow active:scale-[0.98]"
        >
          <div className="w-16 h-16 rounded-full bg-info-50 flex items-center justify-center mb-3">
            <Image size={32} className="text-info-500" />
          </div>
          <span className="text-lg font-semibold text-text-primary">上传截图</span>
          <span className="text-sm text-text-tertiary mt-1">从相册选择</span>
        </button>
      </div>

      <div className="bg-primary-50 rounded-2xl p-4 flex items-start gap-3">
        <Upload size={20} className="text-primary-500 flex-shrink-0 mt-0.5" />
        <div>
          <p className="text-sm font-medium text-primary-700">使用提示</p>
          <p className="text-sm text-primary-600 mt-1">
            可以拍摄或上传短信截图、聊天记录、电话录音界面等，AI 会帮您分析是否有诈骗风险。
          </p>
        </div>
      </div>
    </div>
  );
}
